<?php
namespace App\Livewire\Investor\Support;
use App\Models\SupportTicket;use App\Services\SupportTicketService;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.investor')] class Show extends Component{public SupportTicket $supportTicket;public string $message='';public function mount(SupportTicket $supportTicket):void{abort_unless($supportTicket->investor_id===auth()->user()->investor->id,404);$this->supportTicket=$supportTicket;$supportTicket->update(['investor_last_read_at'=>now()]);}public function reply(SupportTicketService $service):void{$this->validate(['message'=>['required','string','max:5000']]);$service->reply($this->supportTicket,auth()->user(),$this->message);$this->message='';$this->supportTicket->refresh();}public function render(){return view('livewire.investor.support.show',['messages'=>$this->supportTicket->messages()->where('is_internal',false)->with('user')->oldest()->get()])->title('Обращение #'.$this->supportTicket->id.' — CEO Money');}}
